from kb_part1 import ch,N,P,C,F,H,M,O,G,LM,LMH,MH
SAF,SPC,SVC="03_safety_escalation.md","04_operating_specs.md","05_service_guidance.md"
SAFE=["high"]
P2=[
 ch("x500_saf_stop_heat",SAF,"Stop using: burning smell, heat, sparks","safety_escalation",[H],["burning_smell","excessive_heat","sparking"],SAFE,
  "Stop using the device and contact an authorised service centre if: (1) there is a burning smell, any smell of burning plastic or electrical burning during use; (2) the device becomes hot to the touch, beyond mild warmth, within 3 minutes of starting; (3) there is any visible spark or flash near the charging port or motor housing. Do not charge the device again.",True),
 ch("x500_saf_stop_damage",SAF,"Stop using: damage and liquid","safety_escalation",[H,F],["visible_damage","head_joint_damage","exposed_component","water_ingress","lock_ring_damaged","head_detached"],SAFE,
  "Stop using the device and contact an authorised service centre if: (1) there is visible damage such as a cracked casing, broken head joint, bent motor shaft or exposed components; (2) water or liquid has entered the charging port or the body casing seams. Do not use the device if the lock ring is cracked or the head cannot be properly secured, because an unsecured head can detach during use.",True),
 ch("x500_saf_stop_sounds",SAF,"Stop using: electrical sounds and jammed motor","safety_escalation",[H,N],["electrical_crackling","grinding_with_resistance","buzzing_sound","grinding_sound"],SAFE,
  "Stop using the device and contact an authorised service centre if: (1) there are unusual electrical sounds, meaning crackling, buzzing or popping that is not mechanical in nature; (2) there is a grinding noise with resistance, where the shaver struggles and grinds, because the motor may be jammed and forcing it risks further damage or injury.",True),
 ch("x500_saf_no_diy",SAF,"Do not attempt yourself","safety_escalation",[H,F,G],[],MH,
  "Do not open the casing, as there are no user-serviceable parts inside. Do not try to repair the charging port. Do not use third-party blade units that are not approved for the X500, because an incorrect fit causes vibration and noise and may damage the motor shaft. Opening the casing or using non-approved accessories voids the warranty.",True),
 ch("x500_saf_use_limits",SAF,"Safe use limits","safety_escalation",[H,C,M],["excessive_heat","water_exposure_question","slow_charging"],LMH,
  "Maximum continuous use is 10 minutes; let the device cool for 5 minutes before resuming. Do not charge in temperatures above 40 C or below 5 C. Keep away from children under 12. Shower use is permitted with the head attached and the charging port sealed; do not use the shaver near open water.",True),
 ch("x500_spec_sound",SPC,"Normal operating sound","operating_specs",[N],["increased_noise","rattling_sound","grinding_sound","squealing_sound","buzzing_sound"],LMH,
  "Normal sound is a low, steady, smooth hum at about 55 to 62 dB at 30 cm, with a consistent pitch throughout use. Any grinding, rattling, squealing or fluctuating pitch is outside the normal range."),
 ch("x500_spec_vibration",SPC,"Normal vibration","operating_specs",[N],["increased_vibration","irregular_vibration"],LMH,
  "Normal vibration is slight and consistent, comparable to a mild buzz. The flexible head joint absorbs most of it. Abnormal vibration feels like sharp or irregular shaking, or makes the device difficult to hold."),
 ch("x500_spec_temperature",SPC,"Normal temperature","operating_specs",[H],["excessive_heat"],LMH,
  "After 5 minutes of use the body should feel slightly warm, about 30 to 38 C at the surface. Anything above about 45 C at the surface is outside the normal range. The body also becomes slightly warm during charging, which is normal."),
 ch("x500_spec_battery",SPC,"Normal battery behaviour","operating_specs",[C],["battery_drains_fast","slow_charging","not_charging"],LM,
  "A full charge gives 45 minutes of continuous shaving and takes 60 minutes from empty. Battery lifespan is 300 to 500 full charge cycles before capacity noticeably reduces. The red LED comes on at about 10 minutes remaining."),
 ch("x500_spec_blades",SPC,"Normal blade performance","operating_specs",[P,M],["reduced_cutting_quality","pulling_hair","blade_drag","blade_replacement_due"],LM,
  "New blades give a clean, comfortable cut with minimal pulling. Expected blade life is 12 to 18 months under daily use. End-of-life signs are pulling, reduced closeness and more operating sound from blade drag."),
 ch("x500_spec_head_fit",SPC,"Correct head fit","operating_specs",[F],["head_loose","head_wobble","rattling_sound"],LM,
  "A correctly fitted head has no lateral wobble and no vertical play, and rotates smoothly under power. An incorrectly fitted head gives an audible rattle, visible wobble and uneven vibration in the body."),
 ch("x500_svc_noise",SVC,"Service for noise and vibration","service_guidance",[N],["increased_noise","increased_vibration","rattling_sound","grinding_sound"],MH,
  "For noise or vibration a technician inspects the shaving head, lock ring and motor shaft, tests the motor under load to measure speed and acoustic profile, and inspects the motor bearing. Bearing wear is the most common internal cause in devices over 18 months old. The motor assembly or blade unit is replaced as needed, and the casing is cleaned and resealed."),
 ch("x500_svc_battery",SVC,"Service for battery and charging","service_guidance",[C],["battery_drains_fast","not_charging","slow_charging"],MH,
  "For battery issues the technician tests charge capacity, replaces the lithium-ion pack if capacity is below 70% of original, and tests the charging circuit and USB-C port."),
 ch("x500_svc_fit",SVC,"Service for head fitting","service_guidance",[F],["head_loose","head_not_fitting","lock_ring_damaged","head_joint_damage"],MH,
  "For head fitting issues the technician inspects the motor shaft for bending or wear, replaces a stripped or cracked lock ring, and replaces the head assembly if the joint or casing is damaged."),
 ch("x500_svc_power",SVC,"Service for power and electrical issues","service_guidance",[C,H],["not_powering_on","burning_smell","excessive_heat","sparking","electrical_crackling"],MH,
  "For power or electrical issues the technician runs a full diagnostic of the control circuit board, inspects all internal connections, and replaces components or the full unit if the fault is in the main board."),
 ch("x500_svc_bring",SVC,"What to bring and what to say","service_guidance",[G,O],[ "unclear_description","multiple_unresolved_symptoms"],LMH,
  "Bring the device, the original charging cable if the issue involves charging, and proof of purchase if the device is within warranty. Say which X500 you have, what the problem is, when it happens and what you already tried."),
 ch("x500_svc_turnaround",SVC,"Typical turnaround","service_guidance",[G],[],MH,
  "Minor repairs (blade, lock ring, battery) take 2 to 5 business days. Major repairs (motor, circuit board) take 7 to 14 business days. If the unit cannot be repaired, a refurbished replacement of equivalent specification is offered."),
 ch("x500_svc_warranty",SVC,"Warranty repairs","service_guidance",[G],[],MH,
  "Devices within the standard 2-year warranty are repaired or replaced at no charge, provided the fault is not caused by physical damage, liquid ingress beyond rated use, or use of non-approved accessories."),
]
